package net.officefloor.hq.app.invoices;

/**
 * Where an invoice is in its life: still being written, or sent to the client. A sent invoice is
 * part paid while some of it has been paid and some is still due, and paid once nothing is due, or
 * paid late when the payment that cleared it (taking payments in date order) came after its due date;
 * those follow from its payments and are never stored. A sent invoice with something still due
 * more than its client's grace period (a week unless set otherwise) after its due date is overdue, part paid or not; that follows from the date and is never stored.
 * An invoice spread over instalments is instead overdue when any of its instalments is not paid off a
 * week after that instalment's due date (payments pay the instalments in order).
 * A sent invoice with no payments can be voided: it is then void for good, owes nothing and takes no
 * payments or changes.
 * A credit note is a draft until it is issued, when it becomes CREDIT_NOTE for good. A sent invoice
 * whose issued credit notes leave nothing due, with nothing paid, is credited; that follows from its
 * credit notes and is never stored.
                exchangeRates.addDated(date(rate.get("from"), "settings.fxRates[].from"), currency, usdPer);
            }
        }
        for (Map<String, Object> row : rows(fixture.get("clients"), "clients")) {
            only(row, CLIENT_FIELDS, "clients[]");
            String currency = row.get("currency") == null ? Currency.USD.name() : row.get("currency").toString();
            if (Currency.of(currency) == null) {
                throw refuse("unsupported value of clients[].currency: " + currency);
            }
            insert("client", row.get("id"), new String[] {"name", "email", "terms_days", "discount_pct", "tax_exempt", "currency", "early_pay_pct", "early_pay_days", "retention_pct"},
                    text(row, "name"), text(row, "email"), days(row.get("termsDays"), "clients[].termsDays"),
                    percent(row.get("discountPct"), "clients[].discountPct"),
                    flag(row.get("taxExempt"), "clients[].taxExempt"), currency,
                    percent(row.get("earlyPayPct"), "clients[].earlyPayPct"),
                    days(row.get("earlyPayDays"), "clients[].earlyPayDays"),
                    percent(row.get("retentionPct"), "clients[].retentionPct"));
        }
        for (Map<String, Object> row : rows(fixture.get("invoices"), "invoices")) {
            only(row, INVOICE_FIELDS, "invoices[]");
            String status = row.get("status") == null ? "DRAFT" : row.get("status").toString();
            if (!STATUSES.contains(status)) {
                throw refuse("unsupported value of invoices[].status: " + status);
            }
            if ("CREDIT_NOTE".equals(status) && row.get("creditOf") == null) {
                throw refuse("an invoices[] row with status CREDIT_NOTE needs creditOf");
            }
        }
        if (!settings.isEmpty()) {
            out.put("settings", settings);
        }
        out.put("clients", jdbc.queryForList("SELECT id, name, email, terms_days, discount_pct, tax_exempt, currency, early_pay_pct, early_pay_days, retention_pct FROM client ORDER BY id").stream()
                .map(r -> {
                    Map<String, Object> row = new LinkedHashMap<>();
                    row.put("id", r.get("ID"));
                    row.put("name", r.get("NAME"));
                    row.put("email", r.get("EMAIL"));
                    if (r.get("TERMS_DAYS") != null) {
                        row.put("termsDays", r.get("TERMS_DAYS"));
                    }
                    row.put("discountPct", r.get("DISCOUNT_PCT"));
                    row.put("taxExempt", r.get("TAX_EXEMPT"));
                    row.put("currency", r.get("CURRENCY"));
                    row.put("earlyPayPct", r.get("EARLY_PAY_PCT"));
                    if (r.get("EARLY_PAY_DAYS") != null) {
                        row.put("earlyPayDays", r.get("EARLY_PAY_DAYS"));
                    }
                    row.put("retentionPct", r.get("RETENTION_PCT"));
                    return row;
                }).toList());
